"""Generate libvterm's dense portable encoding tables from upstream .tbl data."""

from pathlib import Path
import re


def main():
    directory = Path(__file__).resolve().parent / "src" / "encoding"
    for source in sorted(directory.glob("*.tbl")):
        entries = [0] * 128
        for original in source.read_text(encoding="utf-8").splitlines():
            line = original.split("#", 1)[0].strip()
            if not line:
                continue
            match = re.fullmatch(r'(\d+)/(\d+)\s*=\s*(?:U\+([0-9A-Fa-f]+)|"(.)")', line)
            if not match:
                raise ValueError(f"Unsupported upstream table line: {original!r}")
            high, low, hexadecimal, literal = match.groups()
            index = int(high) * 16 + int(low)
            entries[index] = int(hexadecimal, 16) if hexadecimal else ord(literal)
        lines = ["/* Generated by generate_encoding_tables.py from upstream .tbl. */",
                 f"static const struct StaticTableEncoding encoding_{source.stem} = {{",
                 "  { .decode = &decode_table },", "  {"]
        for start in range(0, 128, 8):
            lines.append("    " + ", ".join(f"0x{value:04x}" for value in entries[start:start + 8]) + ",")
        lines.extend(["  }", "};", ""])
        source.with_suffix(".inc").write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
